centers=[(2,6,8),(3,13,4),(11,14,1),(13,3,2)]
g=[[0]*19 for _ in range(19)]
for r,c,v in centers:
    g[r][c]=v
    for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:g[r+dr][c+dc]=3
# empty plus
for r,c in [(9,8),(11,8),(10,7),(10,9)]:g[r][c]=3
orig=[row[:] for row in g]
# draw each ray, horizontal first; leave the projected empty-center column as a gap
for r,c,v in centers:
    for dc in (-1,1):
        j=c+dc
        while 0<=j<19:
            if j==8: # aperture cast by the uncolored cross
                j+=dc; continue
            if orig[r][j]!=0:
                # own immediate arm only: pass, otherwise stop at the obstacle
                if orig[r][j]==3 and abs(j-c)==1:
                    j+=dc; continue
                break
            g[r][j]=v
            j+=dc
# draw vertical, overwrites horizontal fills but original objects remain
for r,c,v in centers:
    for dr in (-1,1):
        i=r+dr
        while 0<=i<19:
            if orig[i][c]!=0:
                if orig[i][c]==3 and abs(i-r)==1:
                    i+=dr; continue
                break
            g[i][c]=v
            i+=dr
print('\n'.join(' '.join(map(str,row)) for row in g))

